using System;using System.Reflection;using System.Threading.Tasks;using UnityEngine;using Codice.Characters;using Codice.UI;
public static class TestSwordCombo{
static BindingFlags F=BindingFlags.NonPublic|BindingFlags.Instance;static void Set(object o,string n,object v)=>o.GetType().GetField(n,F).SetValue(o,v);static void Call(object o,string n,params object[] a)=>o.GetType().GetMethod(n,F).Invoke(o,a);static void Check(bool v,string s){if(!v)throw new Exception(s);}
public static async Task<string> Run(){for(int i=0;i<100&&!RunHUD.Instance;i++)await Task.Delay(100);var p=RunHUD.Instance.Player;RunHUD.Instance.SetPaused(false);p.SetNarrativeControlsBlocked(false);p.State.Initialize(PlayerClass.Warrior);await Task.Delay(150);p.enabled=false;var c=p.GetComponent<PlayerCombat>();c.enabled=false;Set(c,"nextAttack",0f);Check(c.TryAttack(),"first attack");Check(c.Combo==1,"step1");Check(!c.TryCancelForDodge(),"early cancel allowed");Set(c,"swingElapsed",.7f*(float)c.GetType().GetField("swingDuration",F).GetValue(c));Check(c.CanDefend,"recovery defense blocked");Check(c.TryCancelForDodge()&&!c.IsSwinging,"recovery cancel");Set(c,"nextAttack",0f);Check(c.TryAttack(),"restart");Set(c,"swingElapsed",(float)c.GetType().GetField("swingDuration",F).GetValue(c)*.9f);Check(!c.RequestAttack(),"queue executed too early");Call(c,"UpdateSwing",1f);Set(c,"nextAttack",0f);Call(c,"TickBufferedAttack");Check(c.Combo==2&&c.IsSwinging,"buffer failed");Call(c,"UpdateSwing",1f);Set(c,"nextAttack",0f);Check(c.TryAttack()&&c.Combo==3,"finisher failed");Call(c,"UpdateSwing",1f);Set(c,"nextAttack",0f);Check(c.TryAttack()&&c.Combo==1,"cycle failed");Check(p.GetComponent<Codice.Presentation.ActorPresentation>().Body.HasState(0,Animator.StringToHash("SwordCombo3")),"clips missing");return "Buffer, three-step chain, reset, early cancel refusal, recovery cancel, animation states passed";}}
